function renderScene(c,scene,t,selection){c.save();c.filter='none';c.globalAlpha=1;c.fillStyle=scene.background||'#000';c.fillRect(0,0,state.project.width,state.project.height);for(const el of scene.elements)drawElement(c,el,scene,t,selection&&el.id===state.selectedElementId&&!state.playing&&!state.exporting);c.restore()}
function renderAt(t){
  syncCanvasSize();const info=sceneAt(clamp(t,0,Math.max(0,totalDuration()-.0001))),s=info.scene,next=state.project.scenes[info.index+1];if(state.playing&&s.id!==state.currentSceneId){state.currentSceneId=s.id;state.selectedElementId=null;updateSidebarScene();renderInspector();renderLayers()}
  const d=clamp(+s.transitionDuration||0,0,Math.min(1.5,s.duration)),trans=next&&d>0&&info.local>s.duration-d&&s.transition!=='none';if(!trans){renderScene(ctx,s,info.local,true);return}
  const p=ease('cubic',(info.local-(s.duration-d))/d),W=state.project.width,H=state.project.height;renderScene(aCtx,s,info.local,false);renderScene(bCtx,next,Math.min(next.duration,p*d),false);ctx.save();ctx.clearRect(0,0,W,H);
  if(s.transition==='slide'){ctx.drawImage(bufferA,-p*W,0);ctx.drawImage(bufferB,(1-p)*W,0)}else if(s.transition==='zoom'){ctx.save();ctx.globalAlpha=1-p;ctx.translate(W/2,H/2);ctx.scale(1+p*.08,1+p*.08);ctx.drawImage(bufferA,-W/2,-H/2);ctx.restore();ctx.save();ctx.globalAlpha=p;ctx.translate(W/2,H/2);ctx.scale(.9+p*.1,.9+p*.1);ctx.drawImage(bufferB,-W/2,-H/2);ctx.restore()}else if(s.transition==='wipe'){ctx.drawImage(bufferA,0,0);ctx.save();ctx.beginPath();ctx.rect(0,0,W*p,H);ctx.clip();ctx.drawImage(bufferB,0,0);ctx.restore()}else if(s.transition==='squeeze'){ctx.save();ctx.globalAlpha=1-p;ctx.translate(W/2,H/2);ctx.scale(1,1-p*.9);ctx.drawImage(bufferA,-W/2,-H/2);ctx.restore();ctx.save();ctx.globalAlpha=p;ctx.translate(W/2,H/2);ctx.scale(.2+.8*p,1);ctx.drawImage(bufferB,-W/2,-H/2);ctx.restore()}else if(s.transition==='pushUp'){ctx.drawImage(bufferA,0,-p*H);ctx.drawImage(bufferB,0,(1-p)*H)}else if(s.transition==='iris'){ctx.drawImage(bufferA,0,0);ctx.save();ctx.beginPath();ctx.arc(W/2,H/2,Math.hypot(W,H)*.56*p,0,Math.PI*2);ctx.clip();ctx.drawImage(bufferB,0,0);ctx.restore()}else if(s.transition==='flash'){ctx.drawImage(bufferA,0,0);ctx.globalAlpha=p;ctx.drawImage(bufferB,0,0);ctx.globalAlpha=Math.sin(p*Math.PI)*.48;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,W,H);ctx.globalAlpha=1}else{ctx.drawImage(bufferA,0,0);ctx.globalAlpha=p;ctx.drawImage(bufferB,0,0);ctx.globalAlpha=1}ctx.restore();
}

function setPlayhead(t){state.playhead=clamp(t,0,totalDuration());renderAt(state.playhead);updatePlayheadUi()}
function updatePlayheadUi(){const tc=fmtTime(state.playhead);ui.topTimecode.textContent=tc;ui.bottomTimecode.textContent=tc;ui.playhead.style.left=`${18+state.playhead*timelineScale()}px`}
function play(){if(state.exporting)return;if(state.playing){pause();return}if(state.playhead>=totalDuration()-.02)state.playhead=0;state.playing=true;state.playStartAt=state.playhead;state.playStartNow=performance.now();ui.playBtn.textContent='❚❚';ui.playBtn.setAttribute('aria-label','Pause');playLoop()}
function pause(){state.playing=false;cancelAnimationFrame(state.raf);ui.playBtn.textContent='▶';ui.playBtn.setAttribute('aria-label','Play');renderAt(state.playhead)}
function playLoop(now=performance.now()){if(!state.playing)return;const t=state.playStartAt+(now-state.playStartNow)/1000;if(t>=totalDuration()){state.playhead=totalDuration();updatePlayheadUi();pause();return}state.playhead=t;renderAt(t);updatePlayheadUi();state.raf=requestAnimationFrame(playLoop)}

function canvasPoint(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*state.project.width,y:(e.clientY-r.top)/r.height*state.project.height}}
function hitTest(p){const s=currentScene();for(let i=s.elements.length-1;i>=0;i--){const e=s.elements[i],x=e.x*state.project.width,y=e.y*state.project.height,w=e.w*state.project.width*(e.scale||1),h=e.h*state.project.height*(e.scale||1),dx=p.x-x,dy=p.y-y,a=-(+e.rotation||0)*Math.PI/180,rx=dx*Math.cos(a)-dy*Math.sin(a),ry=dx*Math.sin(a)+dy*Math.cos(a);if(Math.abs(rx)<=w/2+10&&Math.abs(ry)<=h/2+10)return e}return null}
function onCanvasDown(e){if(state.playing||state.exporting)return;const p=canvasPoint(e),hit=hitTest(p);if(hit){state.selectedElementId=hit.id;state.drag={start:p,x:hit.x,y:hit.y};canvas.setPointerCapture(e.pointerId)}else{state.selectedElementId=null}renderInspector();renderLayers();renderTimeline();renderAt(state.playhead)}
function onCanvasMove(e){if(!state.drag)return;const p=canvasPoint(e),el=selectedElement();if(!el)return;el.x=clamp(state.drag.x+(p.x-state.drag.start.x)/state.project.width,-.5,1.5);el.y=clamp(state.drag.y+(p.y-state.drag.start.y)/state.project.height,-.5,1.5);renderAt(state.playhead);updateInspectorXY()}
function onCanvasUp(){if(!state.drag)return;state.drag=null;commitHistory();renderTimeline()}

const animOptions=[['fade','Fade'],['slideUp','Slide up'],['slideDown','Slide down'],['slideLeft','Slide left'],['slideRight','Slide right'],['zoom','Zoom'],['pop','Pop'],['squeezeX','Squeeze X'],['squeezeY','Squeeze Y'],['spin','Spin'],['blur','Blur'],['reveal','Reveal'],['morph','Morph'],['stretch','Stretch'],['whip','Whip'],['flip','Flip']];
const easingOptions=[['smooth','Smooth'],['cubic','Cubic'],['expo','Expo'],['back','Back'],['spring','Spring'],['linear','Linear']];
const loopOptions=[['none','None'],['float','Float'],['pulse','Pulse'],['spin','Spin'],['breathe','Breathe']];
const options=(items,current)=>items.map(([v,l])=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`).join('');

function renderInspector(){
  const el=selectedElement();if(!el){ui.inspectorTitle.textContent='Inspector';ui.inspectorSubtitle.textContent='Select an element';ui.inspectorBody.innerHTML='<div class="empty-state">Select an object on the canvas or add something from the Add tab. Everything important stays in one place.</div>';ui.deleteElementTopBtn.disabled=true;return}
  ui.deleteElementTopBtn.disabled=false;ui.inspectorTitle.textContent=el.name||'Element';ui.inspectorSubtitle.textContent=`${el.type} · ${el.inAnim} in`;
  const textPart=el.type==='text'?`<div class="field"><label>Text</label><textarea data-prop="text">${escapeHtml(el.text)}</textarea></div><div class="row2"><div class="field"><label>Size</label><input data-prop="fontSize" type="number" min="8" max="500" value="${el.fontSize}"></div><div class="field"><label>Weight</label><select data-prop="fontWeight">${[300,400,500,600,700,800,900].map(v=>`<option value="${v}" ${+el.fontWeight===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="row2"><div class="field"><label>Align</label><select data-prop="align">${['left','center','right'].map(v=>`<option value="${v}" ${el.align===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Tracking</label><input data-prop="letterSpacing" type="number" min="-20" max="50" value="${el.letterSpacing||0}"></div></div>`:'';
  ui.inspectorBody.innerHTML=`${textPart}<div class="section-label">Style</div><div class="row2"><div class="field"><label>Fill</label><input data-prop="fill" type="color" value="${el.fill}"></div><div class="field"><label>Opacity</label><input data-prop="opacity" type="range" min="0" max="1" step=".01" value="${el.opacity}"></div></div>${['rect','pill'].includes(el.type)?`<div class="field"><label>Corner radius</label><input data-prop="radius" type="range" min="0" max="300" value="${el.radius||0}"></div>`:''}<div class="row2"><div class="field"><label>Blur</label><input data-prop="blur" type="range" min="0" max="80" value="${el.blur||0}"></div><div class="field"><label>Shadow</label><input data-prop="shadow" type="range" min="0" max="100" value="${el.shadow||0}"></div></div><div class="section-label">Transform</div><div class="row2"><div class="field"><label>X %</label><input data-prop="x" data-scale="100" type="number" step=".1" value="${(el.x*100).toFixed(1)}"></div><div class="field"><label>Y %</label><input data-prop="y" data-scale="100" type="number" step=".1" value="${(el.y*100).toFixed(1)}"></div></div><div class="row2"><div class="field"><label>Width %</label><input data-prop="w" data-scale="100" type="number" min=".1" value="${(el.w*100).toFixed(1)}"></div><div class="field"><label>Height %</label><input data-prop="h" data-scale="100" type="number" min=".1" value="${(el.h*100).toFixed(1)}"></div></div><div class="row2"><div class="field"><label>Rotation</label><input data-prop="rotation" type="number" min="-360" max="360" value="${el.rotation}"></div><div class="field"><label>Scale</label><input data-prop="scale" type="number" min=".05" max="10" step=".05" value="${el.scale}"></div></div><div class="section-label">Motion</div><div class="row2"><div class="field"><label>Animate in</label><select data-prop="inAnim">${options(animOptions,el.inAnim)}</select></div><div class="field"><label>Animate out</label><select data-prop="outAnim">${options(animOptions,el.outAnim)}</select></div></div><div class="row2"><div class="field"><label>Easing</label><select data-prop="easing">${options(easingOptions,el.easing)}</select></div><div class="field"><label>Duration</label><input data-prop="animDuration" type="number" min=".05" max="5" step=".05" value="${el.animDuration}"></div></div><div class="row2"><div class="field"><label>Delay</label><input data-prop="delay" type="number" min="0" max="20" step=".05" value="${el.delay||0}"></div><div class="field"><label>Loop</label><select data-prop="loop">${options(loopOptions,el.loop)}</select></div></div><div class="field"><label>Loop amount</label><input data-prop="loopAmount" type="range" min="0" max="2" step=".05" value="${el.loopAmount||1}"></div><div class="button-row"><button class="text-btn" id="duplicateElementBtn">Duplicate</button><button class="text-btn danger-text" id="deleteElementBtn">Delete</button></div>`;
  qsa('[data-prop]',ui.inspectorBody).forEach(input=>{const evt=input.matches('select,input[type=color],input[type=range]')?'input':'change';input.addEventListener(evt,()=>{const item=selectedElement();if(!item)return;let val=input.value;if(input.type==='number'||input.type==='range')val=+val;if(input.dataset.scale)val/=+input.dataset.scale;item[input.dataset.prop]=val;renderAt(state.playhead);if(['text','inAnim'].includes(input.dataset.prop)){renderLayers();ui.inspectorSubtitle.textContent=`${item.type} · ${item.inAnim} in`}});input.addEventListener('change',()=>{commitHistory();renderTimeline()})});
  qs('#duplicateElementBtn',ui.inspectorBody).addEventListener('click',duplicateElement);qs('#deleteElementBtn',ui.inspectorBody).addEventListener('click',deleteElement);
}
function updateInspectorXY(){const el=selectedElement();if(!el)return;const x=qs('[data-prop="x"]',ui.inspectorBody),y=qs('[data-prop="y"]',ui.inspectorBody);if(x)x.value=(el.x*100).toFixed(1);if(y)y.value=(el.y*100).toFixed(1)}
function renderLayers(){const s=currentScene();ui.layerList.innerHTML=s.elements.slice().reverse().map(el=>`<div class="layer-row ${el.id===state.selectedElementId?'active':''}" data-layer="${el.id}"><span class="layer-icon">${el.type==='text'?'T':el.type==='circle'?'○':el.type==='rect'?'▭':'◇'}</span><span class="layer-name">${escapeHtml(el.name||el.type)}</span><span class="layer-handle">⋮</span></div>`).join('');qsa('[data-layer]',ui.layerList).forEach(row=>row.addEventListener('click',()=>{state.selectedElementId=row.dataset.layer;renderInspector();renderLayers();renderTimeline();renderAt(state.playhead)}))}

function renderSceneList(){
  ui.sceneList.innerHTML=state.project.scenes.map((s,i)=>`<div class="scene-list-item ${s.id===state.currentSceneId?'active':''}" data-scene-list="${s.id}"><header><strong>${escapeHtml(s.name||`Scene ${i+1}`)}</strong><small>${(+s.duration).toFixed(1)}s</small></header><div class="scene-swatch" style="background:${s.background}"></div></div>`).join('');
  qsa('[data-scene-list]',ui.sceneList).forEach(el=>el.addEventListener('click',()=>selectScene(el.dataset.sceneList)));
  const s=currentScene();
  ui.sceneSettings.innerHTML=`<div class="section-label">Selected scene</div><div class="field"><label>Name</label><input id="sceneNameField" type="text" value="${escapeHtml(s.name)}"></div><div class="row2"><div class="field"><label>Duration</label><input id="sceneDurationField" type="number" min=".5" max="120" step=".1" value="${s.duration}"></div><div class="field"><label>Background</label><input id="sceneBackgroundField" type="color" value="${s.background}"></div></div><div class="field"><label>Transition</label><select id="sceneTransitionField">${[['fade','Fade'],['slide','Slide'],['pushUp','Push up'],['zoom','Zoom'],['wipe','Wipe'],['squeeze','Squeeze'],['iris','Iris'],['flash','Flash'],['none','Cut']].map(([v,l])=>`<option value="${v}" ${s.transition===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Transition time</label><input id="sceneTransitionDurationField" type="range" min="0" max="1.5" step=".05" value="${s.transitionDuration??.5}"></div><div class="button-row"><button class="text-btn" id="duplicateSceneBtn">Duplicate</button><button class="text-btn danger-text" id="deleteSceneBtn">Delete</button></div>`;
  const bind=(id,prop,parse=v=>v)=>{const input=qs(`#${id}`,ui.sceneSettings);input.addEventListener('input',()=>{s[prop]=parse(input.value);if(prop==='duration')s.duration=clamp(s.duration,.5,120);ui.sceneTitle.textContent=s.name;renderTimeline();renderAt(state.playhead)});input.addEventListener('change',()=>{commitHistory();renderSceneList()})};
  bind('sceneNameField','name');bind('sceneDurationField','duration',Number);bind('sceneBackgroundField','background');bind('sceneTransitionField','transition');bind('sceneTransitionDurationField','transitionDuration',Number);
  qs('#duplicateSceneBtn',ui.sceneSettings).addEventListener('click',duplicateScene);qs('#deleteSceneBtn',ui.sceneSettings).addEventListener('click',deleteScene);
}
function updateSidebarScene(){renderSceneList();ui.sceneTitle.textContent=currentScene().name}
function selectScene(id){pause();state.currentSceneId=id;state.selectedElementId=null;const s=currentScene();state.playhead=sceneStart(id)+Math.min(.75,s.duration*.18);refreshAll()}
function addScene(afterId=null){const s=makeScene(`Scene ${state.project.scenes.length+1}`,4,'#111217');s.elements=[makeElement('text',{name:'Headline',text:'New scene',fill:'#ffffff',fontSize:130,fontWeight:800}),makeElement('text',{name:'Subtitle',text:'Add your next idea',y:.62,w:.5,h:.06,fill:'#9ea0aa',fontSize:34,fontWeight:500,delay:.32,inAnim:'fade'})];if(afterId){const i=state.project.scenes.findIndex(x=>x.id===afterId);state.project.scenes.splice(i+1,0,s)}else state.project.scenes.push(s);state.currentSceneId=s.id;state.selectedElementId=s.elements.find(e=>e.type==='text')?.id||s.elements[0]?.id||null;state.playhead=sceneStart(s.id)+Math.min(.75,s.duration*.18);commitHistory();refreshAll()}
function duplicateScene(){const src=currentScene(),copy=clone(src);copy.id=uid();copy.name=`${copy.name} copy`;copy.elements.forEach(e=>e.id=uid());const i=state.project.scenes.findIndex(x=>x.id===src.id);state.project.scenes.splice(i+1,0,copy);state.currentSceneId=copy.id;state.selectedElementId=copy.elements.find(e=>e.type==='text')?.id||copy.elements[0]?.id||null;state.playhead=sceneStart(copy.id)+Math.min(.75,copy.duration*.18);commitHistory();refreshAll()}
function deleteScene(){if(state.project.scenes.length<=1){toast('Keep at least one scene','bad');return}const i=state.project.scenes.findIndex(x=>x.id===state.currentSceneId);state.project.scenes.splice(i,1);const next=state.project.scenes[Math.max(0,i-1)];state.currentSceneId=next.id;state.selectedElementId=next.elements.find(e=>e.type==='text')?.id||next.elements[0]?.id||null;state.playhead=sceneStart(next.id);commitHistory();refreshAll()}
function duplicateElement(){const s=currentScene(),e=selectedElement();if(!e)return;const copy=clone(e);copy.id=uid();copy.name=`${copy.name} copy`;copy.x+=.03;copy.y+=.03;s.elements.push(copy);state.selectedElementId=copy.id;commitHistory();refreshAll()}
function deleteElement(){const s=currentScene(),i=s.elements.findIndex(e=>e.id===state.selectedElementId);if(i<0)return;s.elements.splice(i,1);state.selectedElementId=s.elements[Math.min(i,s.elements.length-1)]?.id||null;commitHistory();refreshAll()}
function addElement(kind){const s=currentScene();let e;const dark=!['#f5f5f7','#fafafa','#ffffff'].includes((s.background||'').toLowerCase()),base={x:.5,y:.5,inAnim:'pop',outAnim:'fade',animDuration:.6};if(kind==='heading')e=makeElement('text',{...base,name:'Heading',text:'Your headline',w:.72,h:.18,fontSize:120,fontWeight:800,fill:dark?'#ffffff':'#111111'});else if(kind==='body')e=makeElement('text',{...base,name:'Text',text:'Add a short supporting line.',y:.6,w:.56,h:.08,fontSize:40,fontWeight:500,fill:dark?'#b9bbc4':'#666870'});else if(kind==='rect')e=makeElement('rect',{...base,w:.30,h:.23,fill:'#7c5cff',radius:38});else if(kind==='circle')e=makeElement('circle',{...base,w:.18,h:.32,fill:'#2dd4bf'});else if(kind==='pill')e=makeElement('pill',{...base,w:.24,h:.09,fill:'#7c5cff',radius:999,inAnim:'squeezeX'});else if(kind==='line')e=makeElement('line',{...base,w:.32,h:.03,fill:dark?'#ffffff':'#111111',strokeWidth:8,inAnim:'squeezeX'});else e=makeElement(kind,{...base,w:.11,h:.18,fill:dark?'#ffffff':'#111111',inAnim:'spin'});s.elements.push(e);state.selectedElementId=e.id;commitHistory();refreshAll()}

function timelineScale(){return +ui.timelineZoom.value}
function renderTimeline(){
  const px=timelineScale(),total=totalDuration(),width=Math.max(ui.timelineScroll.clientWidth-2,total*px+36);ui.timelineContent.style.width=`${width}px`;ui.ruler.style.width=`${Math.max(0,width-36)}px`;ui.ruler.innerHTML='';const step=total>30?5:total>15?2:1;for(let t=0;t<=Math.ceil(total);t+=step){const d=document.createElement('div');d.className='tick major';d.style.left=`${t*px}px`;d.innerHTML=`<label>${t}s</label>`;ui.ruler.appendChild(d);if(step===1)for(let k=1;k<4;k++){const s=document.createElement('div');s.className='tick';s.style.left=`${(t+k*.25)*px}px`;ui.ruler.appendChild(s)}}
  ui.sceneTrack.innerHTML=state.project.scenes.map((s,i)=>`<div class="scene-block ${s.id===state.currentSceneId?'active':''}" data-scene-block="${s.id}" style="width:${Math.max(72,s.duration*px)}px"><strong>${escapeHtml(s.name)}</strong><small>${(+s.duration).toFixed(1)}s · ${escapeHtml(s.transition)}</small>${i<state.project.scenes.length-1?`<button class="connector-btn" data-insert-after="${s.id}" title="Insert scene after">＋</button>`:''}<span class="duration-handle" data-resize-scene="${s.id}"></span></div>`).join('');
  qsa('[data-scene-block]',ui.sceneTrack).forEach(block=>block.addEventListener('click',e=>{if(e.target.closest('[data-insert-after],[data-resize-scene]'))return;selectScene(block.dataset.sceneBlock)}));qsa('[data-insert-after]',ui.sceneTrack).forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();addScene(btn.dataset.insertAfter)}));
  qsa('[data-resize-scene]',ui.sceneTrack).forEach(h=>{h.addEventListener('pointerdown',e=>{e.stopPropagation();const s=state.project.scenes.find(x=>x.id===h.dataset.resizeScene);state.resizeScene={scene:s,startX:e.clientX,startDuration:s.duration};h.setPointerCapture(e.pointerId)});h.addEventListener('pointermove',e=>{if(!state.resizeScene)return;state.resizeScene.scene.duration=clamp(Math.round((state.resizeScene.startDuration+(e.clientX-state.resizeScene.startX)/px)*10)/10,.5,120);renderTimeline();renderSceneList();renderAt(state.playhead)});h.addEventListener('pointerup',()=>{if(state.resizeScene){state.resizeScene=null;commitHistory();renderInspector()}})});
  const cs=currentScene(),start=sceneStart(cs.id);ui.elementTracks.innerHTML=cs.elements.slice().reverse().map(el=>{const st=start+(+el.start||0),en=start+(el.end==null?cs.duration:+el.end);return `<div class="element-track" style="width:${Math.max(72,total*px)}px"><div class="element-clip ${el.id===state.selectedElementId?'active':''}" data-clip="${el.id}" style="left:${st*px}px;width:${Math.max(22,(en-st)*px)}px">${escapeHtml(el.name||el.type)}</div></div>`}).join('');qsa('[data-clip]',ui.elementTracks).forEach(c=>c.addEventListener('click',()=>{state.selectedElementId=c.dataset.clip;renderInspector();renderLayers();renderTimeline();renderAt(state.playhead)}));updatePlayheadUi();
}

function snapshotPng(){renderAt(state.playhead);canvas.toBlob(blob=>{if(blob)downloadBlob(blob,'motion-studio-frame.png')},'image/png')}
function syncResolutionSelect(){const v=`${state.project.width}x${state.project.height}`;if([...ui.resolutionSelect.options].some(o=>o.value===v))ui.resolutionSelect.value=v}
function changeResolution(v){const [w,h]=v.split('x').map(Number);state.project.width=w;state.project.height=h;commitHistory();syncCanvasSize();renderAt(state.playhead);toast(`Canvas ${w} × ${h}`,'good')}

function openModal(id){qs(`#${id}`).hidden=false}
function closeModal(id){if(id==='exportModal'&&state.exporting)return;qs(`#${id}`).hidden=true}
function toggleProjectPopover(){ui.projectPopover.hidden=!ui.projectPopover.hidden}
function closeProjectPopover(){ui.projectPopover.hidden=true}
function downloadProject(){downloadBlob(new Blob([JSON.stringify(state.project,null,2)],{type:'application/json'}),'motion-studio-project.json')}
function loadSaved(){try{const raw=localStorage.getItem('motion-studio-autosave');if(!raw){toast('No browser save found','bad');return}const p=JSON.parse(raw);validateProject(p);setProject(p);toast('Browser save loaded','good')}catch(e){toast(`Could not load save: ${e.message}`,'bad')}finally{closeProjectPopover()}}
function validateProject(p){if(!p||!Array.isArray(p.scenes)||!p.scenes.length||!Number.isFinite(+p.width)||!Number.isFinite(+p.height))throw new Error('Invalid project file')}

async function checkFfmpeg(){try{const r=await fetch('status.php',{cache:'no-store'}),j=await r.json();state.ffmpeg=!!j.ffmpeg;ui.ffmpegStatus.textContent=state.ffmpeg?'Available':'Not available';ui.ffmpegStatus.style.color=state.ffmpeg?'#7ee2b8':'#ff98a5'}catch(_){state.ffmpeg=false;ui.ffmpegStatus.textContent='Not available';ui.ffmpegStatus.style.color='#ff98a5'}}
function bestMime(){if(!window.MediaRecorder)return null;const types=['video/mp4;codecs=avc1.42E01E','video/mp4','video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'];return types.find(t=>MediaRecorder.isTypeSupported(t))||''}
async function exportVideo(){
  if(state.exporting)return;if(!canvas.captureStream||!window.MediaRecorder){toast('This browser cannot record the canvas. Use a current Chrome, Edge, Firefox, or Safari.','bad');return}
  pause();state.exporting=true;state.exportCancel=false;ui.startExportBtn.disabled=true;ui.exportProgress.style.width='0%';const fps=+ui.exportFps.value||30,quality=ui.exportQuality.value,duration=totalDuration();state.project.fps=fps;let stream,recorder,chunks=[];
  try{const mime=bestMime();stream=canvas.captureStream(fps);const options={videoBitsPerSecond:quality==='high'?(state.project.width>=1920?16000000:10000000):6000000};if(mime)options.mimeType=mime;recorder=new MediaRecorder(stream,options);recorder.ondataavailable=e=>{if(e.data&&e.data.size)chunks.push(e.data)};const stopped=new Promise((resolve,reject)=>{recorder.onstop=resolve;recorder.onerror=e=>reject(e.error||new Error('Recorder error'))});recorder.start(250);const start=performance.now();ui.exportStatusText.textContent=`Recording ${state.project.width} × ${state.project.height} at ${fps} fps…`;
    await new Promise(resolve=>{const frame=now=>{if(state.exportCancel){resolve();return}const t=Math.min(duration,(now-start)/1000);renderAt(t);ui.exportProgress.style.width=`${(t/duration*100).toFixed(1)}%`;ui.exportStatusText.textContent=`Rendering ${fmtTime(t)} / ${fmtTime(duration)}`;if(t>=duration){resolve();return}requestAnimationFrame(frame)};requestAnimationFrame(frame)});
    if(recorder.state!=='inactive')recorder.stop();await stopped;stream.getTracks().forEach(t=>t.stop());renderAt(state.playhead);if(state.exportCancel){ui.exportStatusText.textContent='Export cancelled.';return}
    const actual=recorder.mimeType||mime||'video/webm',blob=new Blob(chunks,{type:actual});ui.exportProgress.style.width='100%';if(actual.includes('mp4')){downloadBlob(blob,'motion-studio-export.mp4');ui.exportStatusText.textContent='MP4 ready.';toast('MP4 exported','good')}else if(state.ffmpeg){ui.exportStatusText.textContent='Converting recording to MP4…';const form=new FormData();form.append('video',blob,'recording.webm');const res=await fetch('transcode.php',{method:'POST',body:form});if(!res.ok){let msg='MP4 conversion failed';try{const j=await res.json();msg=j.error||msg}catch(_){}throw new Error(msg)}const mp4=await res.blob();downloadBlob(mp4,'motion-studio-export.mp4');ui.exportStatusText.textContent='MP4 ready.';toast('MP4 exported','good')}else{downloadBlob(blob,'motion-studio-export.webm');ui.exportStatusText.textContent='FFmpeg is unavailable, so WebM was downloaded.';toast('WebM exported. Install FFmpeg for MP4 fallback.','bad')}
  }catch(e){console.error(e);ui.exportStatusText.textContent=e.message||'Export failed';toast(e.message||'Export failed','bad')}finally{if(stream)stream.getTracks().forEach(t=>t.stop());state.exporting=false;ui.startExportBtn.disabled=false;renderAt(state.playhead)}
}

